const $=id=>document.getElementById(id), categories=['Produce','Dairy & eggs','Meat & seafood','Bakery','Pantry','Frozen','Household'];
const staples=[['🥛','Milk','Dairy & eggs'],['🥚','Eggs','Dairy & eggs'],['🍌','Bananas','Produce'],['🍞','Bread','Bakery'],['🍚','Rice','Pantry'],['🥬','Spinach','Produce']];
let state={items:[],budget:100,currency:'USD',purchaseHistory:[]},filter='all',shoppingMode=false,filterBeforeShopping='all',storageOK=true;
try{const saved=JSON.parse(localStorage.getItem('basket-v1'));if(saved&&Array.isArray(saved.items)){state.items=saved.items.filter(x=>x&&typeof x.name==='string'&&categories.includes(x.category)&&Number.isFinite(x.qty)&&x.qty>=0.01&&Number.isFinite(x.price)&&x.price>=0);state.purchaseHistory=Array.isArray(saved.purchaseHistory)?saved.purchaseHistory.filter(x=>x&&typeof x.itemId==='string'&&typeof x.name==='string'&&Number.isFinite(x.actualUnitPrice)&&x.actualUnitPrice>=0&&['USD','VND','EUR','GBP'].includes(x.currency)&&Number.isFinite(Date.parse(x.purchasedAt))).slice(-500):[];state.budget=Number.isFinite(saved.budget)&&saved.budget>=0?saved.budget:100;state.language=saved.language==='en'?'en':'vi';state.currency=['USD','VND','EUR','GBP'].includes(saved.currency)?saved.currency:'USD';state.items.forEach(item=>{if(Number.isFinite(item.actualPrice)&&item.actualPrice>=0&&!['USD','VND','EUR','GBP'].includes(item.actualCurrency))item.actualCurrency=state.currency;else if(!Number.isFinite(item.actualPrice)||item.actualPrice<0){delete item.actualPrice;delete item.actualCurrency}});}}catch{}
function save(){try{localStorage.setItem('basket-v1',JSON.stringify(state))}catch{storageOK=false;document.querySelector('.list-foot span').textContent='Browser storage unavailable — copy your list before leaving';}render()}
function money(n){return new Intl.NumberFormat(undefined,{style:'currency',currency:state.currency,maximumFractionDigits:state.currency==='VND'?0:2}).format(n)}
function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(msg){$('toast').textContent=msg;$('toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').style.display='none',2500)}
function add(name,category,qty=1,price=0){state.items.push({id:crypto.randomUUID(),name,category,qty,price,done:false});save()}
function render(){const done=state.items.filter(x=>x.done).length;$('count').textContent=`${done} of ${state.items.length} in basket`;const visible=state.items.filter(x=>filter==='all'||(filter==='done'?x.done:!x.done));$('items').innerHTML=visible.length?categories.map(category=>{const items=visible.filter(x=>x.category===category);return items.length?`<div class="group-title"><span>${escapeHTML(category)}</span><span>${items.length}</span></div>`+items.map(x=>`<div class="item ${x.done?'done':''}" data-id="${escapeHTML(x.id)}"><input class="check" type="checkbox" ${x.done?'checked':''} aria-label="Mark ${escapeHTML(x.name)} as ${x.done?'to buy':'in basket'}"><div class="item-name"><span>${escapeHTML(x.name)}</span><small>${x.price?money(x.price)+' each':'No price added'}</small></div><div class="quantity"><button data-action="minus" aria-label="Decrease quantity of ${escapeHTML(x.name)}" ${x.qty<=1?'disabled':''}>−</button><span>${x.qty}</span><button data-action="plus" aria-label="Increase quantity of ${escapeHTML(x.name)}" ${x.qty>=999?'disabled':''}>+</button></div><span class="item-price">${money(x.price*x.qty)}</span><button class="delete" data-action="delete" aria-label="Remove ${escapeHTML(x.name)}">×</button></div>`).join(''):''}).join(''):`<div class="empty">${state.items.length?(filter==='done'?'Your basket is waiting.<br>Check off an item as you shop.':'Everything is in your basket. Happy cooking!'):'Your next good meal starts here.<br>Add your first item above, or pick a staple below.'}</div>`;const total=state.items.reduce((n,x)=>n+x.price*x.qty,0),bought=state.items.filter(x=>x.done).reduce((n,x)=>n+x.price*x.qty,0);$('total').textContent=money(total);$('bought').textContent=money(bought);$('left').textContent=money(total-bought);$('meter').style.width=(state.budget>0?Math.min(total/state.budget*100,100):total>0?100:0)+'%';$('meter').style.background=total>state.budget?'#a65f40':'#214f38';$('budget-message').textContent=total>state.budget?`${money(total-state.budget)} over your budget`:`${money(state.budget-total)} left in your budget`;$('currency-label').textContent=state.currency;$('clear').disabled=!done;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));}
function setShoppingMode(active){if(Boolean(active)===shoppingMode)return;if(active){filterBeforeShopping=filter;shoppingMode=true;filter='remaining'}else{shoppingMode=false;filter=filterBeforeShopping}document.body.classList.toggle('shopping-mode',shoppingMode);if(shoppingMode&&typeof showMainTab==='function')showMainTab('shopping');render()}
$('budget').value=state.budget;$('currency').value=state.currency;
const shoppingModeToggle=document.createElement('button');shoppingModeToggle.id='shopping-mode-toggle';shoppingModeToggle.type='button';shoppingModeToggle.className='outline shopping-mode-toggle';shoppingModeToggle.addEventListener('click',()=>setShoppingMode(!shoppingMode));document.querySelector('.toolbar').append(shoppingModeToggle);
$('add-form').addEventListener('submit',e=>{e.preventDefault();const name=$('name').value.trim();if(!name){$('name').focus();return}add(name,$('category').value,Number($('qty').value),Number($('price').value)||0);$('name').value='';$('price').value='';$('qty').value=1;$('name').focus();notify('Added to your list')});
$('items').addEventListener('click',e=>{const row=e.target.closest('[data-id]');if(!row)return;const item=state.items.find(x=>x.id===row.dataset.id);if(e.target.matches('.check'))item.done=e.target.checked;else{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='delete')state.items=state.items.filter(x=>x.id!==item.id);else if(action==='plus')item.qty=Math.min(999,item.qty+1);else if(action==='minus')item.qty=Math.max(1,item.qty-1);else return}save()});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render()}));
$('budget').addEventListener('change',()=>{if(!$('budget').checkValidity()){$('budget').reportValidity();return}state.budget=Number($('budget').value)||0;save()});$('currency').addEventListener('change',()=>{state.currency=$('currency').value;save();notify('Currency changed. Enter prices in the selected currency.')});
let cleared=[];$('clear').addEventListener('click',()=>{cleared=state.items.filter(x=>x.done);state.items=state.items.filter(x=>!x.done);save();notify('Checked items cleared — click here to undo');$('toast').onclick=()=>{state.items.push(...cleared);cleared=[];save();notify('Items restored');$('toast').onclick=null}});
$('suggestions').innerHTML=staples.map(([icon,name],i)=>`<button data-staple="${i}">${icon} ${name} ＋</button>`).join('');$('suggestions').addEventListener('click',e=>{const b=e.target.closest('[data-staple]');if(!b)return;const [,name,category]=staples[Number(b.dataset.staple)];add(name,category);notify(`${name} added`)});
$('print').addEventListener('click',()=>window.print());$('copy').addEventListener('click',async()=>{const text=categories.map(c=>{const items=state.items.filter(x=>x.category===c);return items.length?(typeof tr==='function'?tr(c,viCategories[categories.indexOf(c)]):c)+'\n'+items.map(x=>`${x.done?'[x]':'[ ]'} ${x.name} × ${x.qty}${x.unit?" "+x.unit:""} — ${money(x.price*x.qty)}`).join('\n'):''}).filter(Boolean).join('\n\n');try{await navigator.clipboard.writeText(text||'My grocery list is empty.');notify('List copied')}catch{notify('Copy unavailable. Use Print list to save your list.')}});render();
